-- Task 6: self-service-only sample data, hashed QR tokens, test orders and activation.
alter table public.categories add column if not exists is_sample boolean not null default false, add column if not exists sample_seed_version text;
alter table public.menu_items add column if not exists is_sample boolean not null default false, add column if not exists sample_seed_version text;
alter table public.tables add column if not exists is_sample boolean not null default false, add column if not exists sample_seed_version text;
alter table public.orders add column if not exists is_test_order boolean not null default false;
create table if not exists public.public_order_tokens (
 id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, restaurant_id uuid not null references public.restaurants(id) on delete cascade, table_id uuid not null references public.tables(id) on delete cascade, token_hash text not null unique, revoked_at timestamptz, created_at timestamptz not null default clock_timestamp(), unique(table_id) deferrable initially immediate
);
alter table public.public_order_tokens enable row level security;
revoke all on table public.public_order_tokens from public, anon, authenticated;

create or replace function public.create_sample_venue_data()
returns jsonb language plpgsql security definer set search_path=public,extensions as $$
declare p public.onboarding_progress; i int; names text[]:=array['Starters','Mains','Sides','Drinks'];
begin
 select * into p from public.current_self_service_onboarding_context(); if p.id is null then raise exception 'ONBOARDING_ACCESS_DENIED'; end if;
 for i in 1..4 loop insert into public.categories(restaurant_id,name,sort_order,is_sample,sample_seed_version) values(p.venue_id,names[i],i,true,'v1') on conflict(restaurant_id,name) do nothing; end loop;
 for i in 1..12 loop insert into public.menu_items(restaurant_id,category_id,name,description,price,local_id,category,sort_order,is_sample,sample_seed_version) select p.venue_id,c.id,'Sample item '||i,'Sample menu item',10+i,'sample-v1-'||i,c.name,i,true,'v1' from public.categories c where c.restaurant_id=p.venue_id and c.is_sample order by c.sort_order limit 1 offset ((i-1)%4) on conflict(restaurant_id,local_id) do nothing; end loop;
 for i in 1..5 loop insert into public.tables(restaurant_id,table_number,table_name,local_id,name,table_token,sort_order,is_sample,sample_seed_version) values(p.venue_id,i,'Sample table '||i,'sample-v1-'||i,'Sample table '||i,encode(gen_random_bytes(18),'hex'),i,true,'v1') on conflict(restaurant_id,local_id) do nothing; end loop;
 update public.onboarding_step_progress set status='completed',completed_at=coalesce(completed_at,clock_timestamp()),last_updated_at=clock_timestamp() where venue_id=p.venue_id and step_key in('menu','tables');
 return public.get_current_onboarding(); end $$;
create or replace function public.remove_sample_venue_data() returns void language plpgsql security definer set search_path=public,extensions as $$ declare p public.onboarding_progress; begin select * into p from public.current_self_service_onboarding_context(); if p.id is null then raise exception 'ONBOARDING_ACCESS_DENIED'; end if; delete from public.tables where restaurant_id=p.venue_id and is_sample; delete from public.menu_items where restaurant_id=p.venue_id and is_sample; delete from public.categories where restaurant_id=p.venue_id and is_sample; end $$;
create or replace function public.generate_current_qr_token(p_table_id uuid) returns text language plpgsql security definer set search_path=public,extensions as $$ declare p public.onboarding_progress; raw text:=encode(gen_random_bytes(32),'base64'); begin select * into p from public.current_self_service_onboarding_context(); if p.id is null or not exists(select 1 from public.tables where id=p_table_id and restaurant_id=p.venue_id and is_active) then raise exception 'QR_ACCESS_DENIED'; end if; delete from public.public_order_tokens where table_id=p_table_id; insert into public.public_order_tokens(organization_id,restaurant_id,table_id,token_hash) values(p.organization_id,p.venue_id,p_table_id,encode(digest(raw,'sha256'),'hex')); update public.onboarding_step_progress set status='completed',completed_at=coalesce(completed_at,clock_timestamp()),last_updated_at=clock_timestamp() where venue_id=p.venue_id and step_key='qr_code'; return raw; end $$;
create or replace function public.get_current_qr_tables() returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare p public.onboarding_progress; begin select * into p from public.current_self_service_onboarding_context(); if p.id is null then raise exception 'ONBOARDING_ACCESS_DENIED'; end if; return coalesce((select jsonb_agg(jsonb_build_object('id',t.id,'name',t.name,'table_number',t.table_number,'qr_active',q.id is not null) order by t.sort_order) from public.tables t left join public.public_order_tokens q on q.table_id=t.id and q.revoked_at is null where t.restaurant_id=p.venue_id and t.is_active),'[]'::jsonb); end $$;
create or replace function public.revoke_current_qr_token(p_table_id uuid) returns void language plpgsql security definer set search_path=public,extensions as $$ declare p public.onboarding_progress; begin select * into p from public.current_self_service_onboarding_context(); if p.id is null or not exists(select 1 from public.tables where id=p_table_id and restaurant_id=p.venue_id) then raise exception 'QR_ACCESS_DENIED'; end if; update public.public_order_tokens set revoked_at=clock_timestamp() where table_id=p_table_id and revoked_at is null; update public.onboarding_step_progress set status='in_progress',last_updated_at=clock_timestamp() where venue_id=p.venue_id and step_key='qr_code'; end $$;
create or replace function public.resolve_public_order_token(p_token text) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare t public.public_order_tokens; begin select * into t from public.public_order_tokens where token_hash=encode(digest(p_token,'sha256'),'hex') and revoked_at is null; if t.id is null then raise exception 'PUBLIC_TOKEN_NOT_FOUND'; end if; return jsonb_build_object('restaurant_slug',(select slug from public.restaurants where id=t.restaurant_id),'table_name',(select name from public.tables where id=t.table_id)); end $$;
create or replace function public.create_onboarding_test_order() returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare p public.onboarding_progress; o uuid; begin select * into p from public.current_self_service_onboarding_context(); if p.id is null then raise exception 'ONBOARDING_ACCESS_DENIED'; end if; if exists(select 1 from public.orders where restaurant_id=p.venue_id and is_test_order and status<>'completed') then return jsonb_build_object('id',(select id from public.orders where restaurant_id=p.venue_id and is_test_order and status<>'completed' order by created_at desc limit 1),'is_test_order',true,'existing',true); end if; if not exists(select 1 from public.menu_items where restaurant_id=p.venue_id and is_active and is_available) or not exists(select 1 from public.tables where restaurant_id=p.venue_id and is_active) then raise exception 'TEST_ORDER_PREREQUISITES_MISSING'; end if; insert into public.orders(restaurant_id,table_id,status,subtotal,total,tax,note,is_test_order) values(p.venue_id,(select id from public.tables where restaurant_id=p.venue_id and is_active limit 1),'new',0,0,0,'Onboarding test order',true) returning id into o; update public.onboarding_step_progress set status='in_progress',last_updated_at=clock_timestamp() where venue_id=p.venue_id and step_key='test_order'; return jsonb_build_object('id',o,'is_test_order',true,'existing',false); end $$;
create or replace function public.activate_current_venue() returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare p public.onboarding_progress; missing text[]; begin select * into p from public.current_self_service_onboarding_context(); if p.id is null then raise exception 'ONBOARDING_ACCESS_DENIED'; end if; select array_agg(s) into missing from unnest(array['business_details','venue_details','menu','tables','qr_code','test_order']) s where not exists(select 1 from public.onboarding_step_progress x where x.venue_id=p.venue_id and x.step_key=s and x.status='completed'); if coalesce(array_length(missing,1),0)>0 then return jsonb_build_object('activated',false,'blocking_reasons',missing); end if; if public.organization_entitlement_effective_status(p.organization_id) not in('trial','active') then return jsonb_build_object('activated',false,'blocking_reasons',array['ACTIVE_ENTITLEMENT_REQUIRED']); end if; update public.restaurants set venue_status='active',ordering_enabled=true,is_open=true,status='active' where id=p.venue_id and ordering_enabled=false; return jsonb_build_object('activated',true,'blocking_reasons',array[]::text[]); end $$;
create or replace function public.get_public_order_context(p_token text) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare t public.public_order_tokens; begin select * into t from public.public_order_tokens where token_hash=encode(digest(p_token,'sha256'),'hex') and revoked_at is null; if t.id is null then raise exception 'PUBLIC_TOKEN_NOT_FOUND'; end if; if not exists(select 1 from public.restaurants where id=t.restaurant_id and ordering_enabled and is_active) then raise exception 'PUBLIC_ORDERING_UNAVAILABLE'; end if; return jsonb_build_object('restaurant_slug',(select slug from public.restaurants where id=t.restaurant_id),'restaurant_name',(select name from public.restaurants where id=t.restaurant_id),'table_name',(select name from public.tables where id=t.table_id),'menu',(select coalesce(jsonb_agg(jsonb_build_object('id',m.id,'name',m.name,'description',m.description,'price',m.price,'category',m.category)),'[]'::jsonb) from public.menu_items m where m.restaurant_id=t.restaurant_id and m.is_active and m.is_available)); end $$;
create or replace function public.submit_public_token_order(p_token text,p_items jsonb,p_customer_name text default '',p_note text default '') returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare t public.public_order_tokens; o uuid; total numeric; begin if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'INVALID_ORDER_ITEMS'; end if; select * into t from public.public_order_tokens where token_hash=encode(digest(p_token,'sha256'),'hex') and revoked_at is null; if t.id is null then raise exception 'PUBLIC_TOKEN_NOT_FOUND'; end if; perform public.assert_restaurant_live_order_entitlement(t.restaurant_id); if not exists(select 1 from public.restaurants where id=t.restaurant_id and ordering_enabled and is_active) then raise exception 'PUBLIC_ORDERING_UNAVAILABLE'; end if; select coalesce(sum(m.price*(i->>'quantity')::int),0) into total from jsonb_array_elements(p_items)i join public.menu_items m on m.id=(i->>'menu_item_id')::uuid and m.restaurant_id=t.restaurant_id and m.is_active and m.is_available; if total<=0 then raise exception 'INVALID_ORDER_ITEMS'; end if; insert into public.orders(restaurant_id,table_id,customer_name,note,subtotal,total,tax,is_test_order) values(t.restaurant_id,t.table_id,left(coalesce(p_customer_name,''),120),left(coalesce(p_note,''),500),total,total,0,false) returning id into o; insert into public.order_items(restaurant_id,order_id,menu_item_id,item_name,quantity,price,name_snapshot,base_price,unit_price) select t.restaurant_id,o,m.id,m.name,(i->>'quantity')::int,m.price,m.name,m.price,m.price from jsonb_array_elements(p_items)i join public.menu_items m on m.id=(i->>'menu_item_id')::uuid and m.restaurant_id=t.restaurant_id; return jsonb_build_object('order_number',(select order_number from public.orders where id=o)); end $$;
create or replace function public.complete_onboarding_test_order(p_order_id uuid) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare p public.onboarding_progress; begin select * into p from public.current_self_service_onboarding_context(); if p.id is null then raise exception 'ONBOARDING_ACCESS_DENIED'; end if; update public.orders set status='completed',closed_at=clock_timestamp() where id=p_order_id and restaurant_id=p.venue_id and is_test_order; if not found then raise exception 'TEST_ORDER_NOT_FOUND'; end if; update public.onboarding_step_progress set status='completed',completed_at=coalesce(completed_at,clock_timestamp()),last_updated_at=clock_timestamp() where venue_id=p.venue_id and step_key='test_order'; return public.get_current_onboarding(); end $$;
revoke all on function public.get_public_order_context(text),public.submit_public_token_order(text,jsonb,text,text),public.complete_onboarding_test_order(uuid) from public;
grant execute on function public.get_public_order_context(text),public.submit_public_token_order(text,jsonb,text,text) to anon,authenticated;
grant execute on function public.complete_onboarding_test_order(uuid) to authenticated;
create or replace function public.sync_completed_test_order_onboarding() returns trigger language plpgsql security definer set search_path=public,extensions as $$ begin if new.is_test_order and new.status='completed' and old.status is distinct from 'completed' then update public.onboarding_step_progress set status='completed',completed_at=coalesce(completed_at,clock_timestamp()),last_updated_at=clock_timestamp() where venue_id=new.restaurant_id and step_key='test_order'; end if; return new; end $$;
drop trigger if exists sync_completed_test_order_onboarding on public.orders;
create trigger sync_completed_test_order_onboarding after update of status on public.orders for each row execute function public.sync_completed_test_order_onboarding();
revoke all on function public.sync_completed_test_order_onboarding() from public,anon,authenticated;
revoke all on function public.get_current_qr_tables(),public.revoke_current_qr_token(uuid) from public,anon;
grant execute on function public.get_current_qr_tables(),public.revoke_current_qr_token(uuid) to authenticated;
create or replace function public.activate_current_venue() returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare p public.onboarding_progress; missing text[]:=array[]::text[]; begin select * into p from public.current_self_service_onboarding_context(); if p.id is null then raise exception 'ONBOARDING_ACCESS_DENIED'; end if; if exists(select 1 from public.onboarding_step_progress where venue_id=p.venue_id and step_key in('business_details','venue_details') and status<>'completed') then missing:=array_append(missing,'DETAILS_INCOMPLETE'); end if; if not exists(select 1 from public.menu_items where restaurant_id=p.venue_id and is_active and is_available) then missing:=array_append(missing,'ORDERABLE_MENU_REQUIRED'); end if; if not exists(select 1 from public.tables where restaurant_id=p.venue_id and is_active) then missing:=array_append(missing,'ACTIVE_TABLE_REQUIRED'); end if; if not exists(select 1 from public.public_order_tokens where restaurant_id=p.venue_id and revoked_at is null) then missing:=array_append(missing,'ACTIVE_QR_REQUIRED'); end if; if not exists(select 1 from public.orders where restaurant_id=p.venue_id and is_test_order and status='completed') then missing:=array_append(missing,'COMPLETED_TEST_ORDER_REQUIRED'); end if; if public.organization_entitlement_effective_status(p.organization_id) not in('trial','active') then missing:=array_append(missing,'ACTIVE_ENTITLEMENT_REQUIRED'); end if; if cardinality(missing)>0 then return jsonb_build_object('activated',false,'blocking_reasons',missing); end if; update public.restaurants set venue_status='active',ordering_enabled=true,is_open=true,status='active' where id=p.venue_id and not ordering_enabled; return jsonb_build_object('activated',true,'blocking_reasons',array[]::text[]); end $$;
create or replace function public.get_current_venue_readiness() returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare p public.onboarding_progress; missing text[]:=array[]::text[]; begin select * into p from public.current_self_service_onboarding_context(); if p.id is null then raise exception 'ONBOARDING_ACCESS_DENIED'; end if; if exists(select 1 from public.onboarding_step_progress where venue_id=p.venue_id and step_key in('business_details','venue_details') and status<>'completed') then missing:=array_append(missing,'DETAILS_INCOMPLETE'); end if; if not exists(select 1 from public.menu_items where restaurant_id=p.venue_id and is_active and is_available) then missing:=array_append(missing,'ORDERABLE_MENU_REQUIRED'); end if; if not exists(select 1 from public.tables where restaurant_id=p.venue_id and is_active) then missing:=array_append(missing,'ACTIVE_TABLE_REQUIRED'); end if; if not exists(select 1 from public.public_order_tokens where restaurant_id=p.venue_id and revoked_at is null) then missing:=array_append(missing,'ACTIVE_QR_REQUIRED'); end if; if not exists(select 1 from public.orders where restaurant_id=p.venue_id and is_test_order and status='completed') then missing:=array_append(missing,'COMPLETED_TEST_ORDER_REQUIRED'); end if; if public.organization_entitlement_effective_status(p.organization_id) not in('trial','active') then missing:=array_append(missing,'ACTIVE_ENTITLEMENT_REQUIRED'); end if; return jsonb_build_object('ready',cardinality(missing)=0,'blocking_reasons',missing); end $$;
revoke all on function public.get_current_venue_readiness() from public,anon;
grant execute on function public.get_current_venue_readiness() to authenticated;
revoke all on function public.create_sample_venue_data(),public.remove_sample_venue_data(),public.generate_current_qr_token(uuid),public.create_onboarding_test_order(),public.activate_current_venue() from public,anon;
grant execute on function public.create_sample_venue_data(),public.remove_sample_venue_data(),public.generate_current_qr_token(uuid),public.create_onboarding_test_order(),public.activate_current_venue() to authenticated;
grant execute on function public.resolve_public_order_token(text) to anon,authenticated;
notify pgrst,'reload schema';
